"""Bind the portable packed engine and exact geometry to a stable SHA-256.

The digest hashes UTF-8 JSON with sorted keys, no whitespace and ensure_ascii=True.
The file manifest uses the fixed logical names below, independent of source path.
This identifies code/configuration, not a signature or proof of device installation.
"""
import argparse
import hashlib
import json
import re
from pathlib import Path

FW = Path(__file__).resolve().parents[1]
NAMES = ('packed_fs.c', 'packed_fs.h', 'lfs.c', 'lfs.h', 'lfs_util.c', 'lfs_util.h')

def identity(core, littlefs):
    files = {n: (core if n.startswith('packed_') else littlefs) / n for n in NAMES}
    header = files['packed_fs.h'].read_text(encoding='utf-8')
    expected = dict(FORMAT_VERSION=1, BLOCK_SIZE=4096, BLOCK_COUNT=512, CACHE_SIZE=256,
                    SHARD_TARGET=32768, MAX_SHARDS=64, MAX_HANDLES=8, PATH_MAX=64,
                    NAME_MAX=48, META_SIZE=128)
    for name, value in expected.items():
        found = re.search(r'^#define PFS_' + name + r'\s+(\d+)u?\s*$', header, re.M)
        assert found and int(found[1]) == value, ('layout changed', name)
    manifest = dict(schema=1, format='PFS1', constants=expected,
                    defines=['LFS_NO_ASSERT', 'LFS_NO_DEBUG', 'LFS_NO_ERROR', 'LFS_NO_MALLOC', 'LFS_NO_WARN'], files={n: hashlib.sha256(p.read_bytes()).hexdigest()
                                                    for n, p in files.items()})
    canonical = json.dumps(manifest, sort_keys=True, separators=(',', ':'), ensure_ascii=True).encode('utf-8')
    return manifest, hashlib.sha256(canonical).hexdigest()

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--core', type=Path, default=FW / 'application/src/mod/vfs')
    parser.add_argument('--littlefs', type=Path, default=FW / 'components/littlefs')
    parser.add_argument('--header', type=Path)
    parser.add_argument('--json', type=Path)
    args = parser.parse_args()
    manifest, digest = identity(args.core, args.littlefs)
    if args.header:
        values = ', '.join('0x'+digest[i:i+2] for i in range(0, 64, 2))
        args.header.write_text('/* Generated by scripts/packed_identity.py. */\n#ifndef VFS_PACKED_IDENTITY_H\n'
                              '#define VFS_PACKED_IDENTITY_H\n#define PIXL_PACKED_ENGINE_SHA256_BYTES {'
                              + values + '}\n#define PIXL_PACKED_ENGINE_SHA256 "' + digest + '"\n#endif\n', encoding='utf-8')
    result = dict(manifest=manifest, engineSha256=digest)
    if args.json:
        args.json.write_text(json.dumps(result, indent=2)+'\n', encoding='utf-8')
    print(digest)

if __name__ == '__main__':
    main()
